// Server-side localized city name lookup.
// Data files live in data/city-names/<locale>.json (generated by scripts/build-city-names.mjs).
// data/city-names/overrides.json holds manual high-priority overrides (formerly lib/cityNames.ts NAMES).
import { readFileSync } from "node:fs";
import path from "node:path";
import { isLocale } from "@/i18n/routing";

const cache = new Map<string, Record<string, string>>();
const overridesCache: { data: Record<string, Record<string, string>> | null } = { data: null };
const wikidataCache: { data: Record<string, Record<string, string>> | null } = { data: null };

function loadOverrides(): Record<string, Record<string, string>> {
  if (overridesCache.data) return overridesCache.data;
  try {
    const p = path.join(process.cwd(), "data", "city-names", "overrides.json");
    overridesCache.data = JSON.parse(readFileSync(p, "utf8"));
    return overridesCache.data!;
  } catch {
    overridesCache.data = {};
    return overridesCache.data!;
  }
}

function loadWikidata(): Record<string, Record<string, string>> {
  if (wikidataCache.data) return wikidataCache.data;
  try {
    const p = path.join(process.cwd(), "data", "city-names", "wikidata.json");
    wikidataCache.data = JSON.parse(readFileSync(p, "utf8"));
    return wikidataCache.data!;
  } catch {
    wikidataCache.data = {};
    return wikidataCache.data!;
  }
}

function load(locale: string): Record<string, string> {
  if (cache.has(locale)) return cache.get(locale)!;
  try {
    const p = path.join(process.cwd(), "data", "city-names", `${locale}.json`);
    const data = JSON.parse(readFileSync(p, "utf8"));
    cache.set(locale, data);
    return data;
  } catch {
    cache.set(locale, {});
    return {};
  }
}

/** Localized city name, falling back to English then the provided fallback. */
export function cityName(code: string, locale: string, fallback?: string): string {
  const loc = isLocale(locale) ? locale : "en";
  const overrides = loadOverrides();
  const ov = overrides[loc] && overrides[loc][code.toUpperCase()];
  if (ov) return ov;
  const wikidata = loadWikidata();
  const wv = wikidata[loc] && wikidata[loc][code.toUpperCase()];
  if (wv) return wv;
  const data = load(loc);
  if (data[code]) return data[code];
  if (loc !== "en") {
    const en = load("en");
    if (en[code]) return en[code];
  }
  return fallback ?? code;
}

/** Lower-cased, accent- and diacritic-insensitive form used for matching what the visitor types. */
export const norm = (s: string) =>
  s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f\u064b-\u065f\u0670]/g, "");
